function performFormalHatVerification() {
  const parity = bits => bits.reduce((p, b) => p ^ b, 0);
  function simulate(hats) {
    const n = hats.length;
    const answers = new Array(n);
    const signal = parity(hats.slice(1));
    answers[0] = signal;
    const trace = [{
      speaker: 1, role: "parity-message",
      visibleHats: hats.slice(1),
      visibleBlackCount: hats.slice(1).reduce((a,b)=>a+b,0),
      answer: signal, actualHat: hats[0], correct: signal === hats[0]
    }];
    for (let i = 1; i < n; i++) {
      const visible = hats.slice(i + 1);
      const priorRealAnswers = answers.slice(1, i);
      const remainingParity = signal ^ parity(priorRealAnswers);
      const answer = signal ^ parity(visible) ^ parity(priorRealAnswers);
      answers[i] = answer;
      trace.push({
        speaker: i + 1, role: "actual-hat",
        visibleHats: visible,
        visibleBlackCount: visible.reduce((a,b)=>a+b,0),
        priorRealAnswers,
        priorActualBlackCount: priorRealAnswers.reduce((a,b)=>a+b,0),
        remainingParityBeforeAnswer: remainingParity,
        answer, actualHat: hats[i], correct: answer === hats[i],
        remainingParityAfterAnswer: remainingParity ^ answer
      });
    }
    return {answers, trace};
  }
  const rows = [];
  let assignments = 0;
  let verifiedOtherSpeakerTurns = 0;
  let firstSpeakerOwnFlipPairs = 0;
  for (let n = 1; n <= 14; n++) {
    let exactlyNMinus1Correct = 0;
    let exactlyNCorrect = 0;
    let firstSpeakerIncorrect = 0;
    let pairs = 0;
    for (let mask = 0; mask < 2 ** n; mask++) {
      const hats = Array.from({length:n}, (_,i)=>(mask >> i) & 1);
      const result = simulate(hats);
      if (!result.answers.slice(1).every((a,i)=>a === hats[i+1])) {
        throw Error("Wrong later answer: n=" + n + ",mask=" + mask);
      }
      for (let i = 1; i < n; i++) {
        const remainingFromAnswers = result.answers[0] ^ parity(result.answers.slice(1,i));
        const actualRemaining = parity(hats.slice(i));
        if (remainingFromAnswers !== actualRemaining) throw Error("Invariant failed");
        verifiedOtherSpeakerTurns++;
      }
      const correct = result.answers.reduce((count,a,i)=>count + Number(a === hats[i]), 0);
      if (correct === n) exactlyNCorrect++;
      else if (correct === n-1) exactlyNMinus1Correct++;
      else throw Error("Unexpected guaranteed score");
      if (result.answers[0] !== hats[0]) firstSpeakerIncorrect++;
      if (hats[0] === 0) {
        const flipped = hats.slice();
        flipped[0] = 1;
        if (simulate(flipped).answers[0] !== result.answers[0]) throw Error("Own hat leaked");
        pairs++;
        firstSpeakerOwnFlipPairs++;
      }
      assignments++;
    }
    rows.push({
      n, assignments: 2 ** n,
      allLaterSpeakersCorrect: true,
      exactlyNMinus1Correct, exactlyNCorrect,
      firstSpeakerIncorrect, ownFlipPairs: pairs
    });
  }
  const fixtures = [
    {name:"all-white", hats:Array(100).fill(0)},
    {name:"all-black", hats:Array(100).fill(1)},
    {name:"alternating-white-start", hats:Array.from({length:100},(_,i)=>i % 2)},
    {name:"alternating-black-start", hats:Array.from({length:100},(_,i)=>(i+1) % 2)},
    ...Array.from({length:100},(_,j)=>({
      name:"single-black-" + (j+1),
      hats:Array.from({length:100},(_,i)=>i === j ? 1 : 0)
    })),
    ...Array.from({length:100},(_,j)=>({
      name:"single-white-" + (j+1),
      hats:Array.from({length:100},(_,i)=>i === j ? 0 : 1)
    }))
  ];
  for (const f of fixtures) {
    if (!simulate(f.hats).answers.slice(1).every((a,i)=>a === f.hats[i+1])) {
      throw Error("100-person fixture failed: " + f.name);
    }
  }
  const formalHats = [0,1,0,1,1];
  const formalExample = simulate(formalHats);
  const wrongAnswers = new Array(formalHats.length);
  wrongAnswers[0] = parity(formalHats.slice(1));
  for (let i = 1; i < formalHats.length; i++) {
    wrongAnswers[i] = wrongAnswers[0] ^ parity(formalHats.slice(i+1)) ^
                      parity(wrongAnswers.slice(0,i));
  }
  return {
    executionContext:"A new actual functions V8 replay; no Node, filesystem or randomness.",
    numbering:"1=rear/first speaker; n=front/last speaker; answer order1..n; sees larger IDs; black1/white0.",
    assignments,
    verifiedOtherSpeakerTurns,
    firstSpeakerOwnFlipPairs,
    rows,
    deterministic100PersonFixtures:{
      count:fixtures.length,
      construction:"2 monochrome +2 alternating +100 single-black +100 single-white",
      all99LaterSpeakersCorrect:true,
      notExhaustiveAndNotTheProof:true
    },
    formalExample:{hats:formalHats,...formalExample},
    negativeControl:{
      error:"Counts the first parity message as an actual prior hat color",
      hats:formalHats,
      wrongAnswers,
      wrongSpeakers:wrongAnswers.map((a,i)=>a === formalHats[i] ? null : i+1).filter(x=>x !== null)
    }
  };
}
